async function getScannerScript(cwd: string): Promise<string> {
  const toolScript = join(cwd, 'tools/ai_studio_tool/file_scanner.py');
  try {
    await access(toolScript);
    return 'tools/ai_studio_tool/file_scanner.py';
  } catch {
    return 'tools/ai_studio_tool/file_scanner.py';
  }
}

const app = express();
