    await execFilePromise('python3', [script, 'public/topology.json'], { cwd });
    const jsonContent = await readFile(join(cwd, 'public/topology.json'), 'utf-8');
    res.setHeader('Content-Type', 'application/json');
    res.send(jsonContent);
